def pairfill(seglist, original, n=16):
 f=set()
 for i,(u1,lo1,hi1) in enumerate(seglist):
  for u2,lo2,hi2 in seglist[i+1:]:
   lo=max(lo1,lo2);hi=min(hi1,hi2)
   if lo>hi: continue
   for r in range(n):
    for c in range(n):
     u=r+c;v=r-c
     if min(u1,u2)<u<max(u1,u2) and lo<=v<=hi and (r,c) not in original: f.add((r,c))
 return f
